   "caption_excerpt": "Save this for your next trip🇯🇵✈️🔽\n\nHi\nこんにちは（kon nichi wa）\n\nYes\nはい（hai）\n\nNo\nいいえ（iie）\n\nPlease \nおねがいします（onegai shimasu）\n\nThank you\nありがとうございます（arigatou gozaimasu）\n\nExcuse me / Sorry\nすみません（sumimasen）\n\nNo thank you\nけっこうです（kekkou desu）\n\nIt’s okay\nだいじょうぶです（daijoubu desu）\n\nHow much?\nいくらですか？（ikura desu ka）\n\nI’ll have this\nこれくださ…",
   "transcript_excerpt": "You're not ready to visit Japan, if you can't say these. Hi!こんにちは! Yes! Hi! No! いいえ! Please! お願いします! Thank you! ありがとうございます! Excuse me or sorry! すみません! No! Thank you! 結構です! It's okay! 大丈夫です! How much? いくらですか? I'll have this! これください! バイクレディカード! カードで バイキャッシュ! 元金で! See you again! またきます!"
